#!/usr/bin/env python3
"""Write a satcore --pairmap for the edge orbits of the cyclic group generated by a
permutation of 0..n-1 made of cycles of the given lengths (in order of vertices).
usage: orbitmap.py N CYCLE_LEN... > map     e.g. orbitmap.py 39 13 13 13"""
import sys
n = int(sys.argv[1]); lens = [int(x) for x in sys.argv[2:]]
assert sum(lens) <= n
perm = list(range(n)); v = 0
for L in lens:
    for t in range(L): perm[v + t] = v + (t + 1) % L
    v += L
var = {}; nv = 0
for j in range(n):
    for i in range(j):
        if (i, j) in var: continue
        nv += 1; a, b = i, j
        while True:
            key = (min(a, b), max(a, b))
            if key in var: break
            var[key] = nv; a, b = perm[a], perm[b]
for j in range(n):
    for i in range(j): print(i, j, var[(i, j)])
print('# orbits', nv, file=sys.stderr)
